const atDate=d=>d?d.slice(0,10).split('-').reverse().map((x,i)=>i===1?['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(x)-1]:x).join(' '):'';
const atMins=m=>m>=60?Math.floor(m/60)+'h '+(m%60?String(m%60).padStart(2,'0')+'m':'00m'):m+'m';
const atOverdue=d=>d&&Date.parse(d)<Date.parse('2026-09-15');
