const atKv=(k,v)=>`<div class="line"><span>${k}</span><strong>${v}</strong></div>`;
const atSel=(name,opts,val='',extra='')=>`<select name="${name}" ${extra}><option value="">Choose</option>${opts.map(o=>`<option ${String(val)===String(o)?'selected':''}>${o}</option>`).join('')}</select>`;
const atBadge=s=>badge(s,s==='Completed'?'':s==='Scheduled'||s==='Pending'?'lilac':s==='Overdue'||s==='Absent'||s==='Missing'?'red':s==='Late'||s==='Open'?'amber':'gray');
const atTimeline=items=>items.length?`<ol class="timeline">${items.map(e=>`<li>${esc(e.t)}<small>${esc(e.d)} / ${esc(e.u)}</small></li>`).join('')}</ol>`:'<p class="subtle">No entries yet.</p>';
