const trPassed=(t,p)=>!t.assessment||(p.score!=null&&p.score>=t.passMark);
const trRecorded=t=>t.participants.every(p=>p.attendance);
const trScored=t=>!t.assessment||t.participants.filter(p=>p.attendance==='Present'||p.attendance==='Late').every(p=>p.score!=null);
const trEvidence=t=>t.docs.some(d=>d[0]==='Attendance sheet'&&d[1]==='Uploaded');
const trMissingEvidence=t=>t.status==='Completed'?t.participants.filter(p=>(p.attendance==='Present'||p.attendance==='Late')&&p.certificate!=='Uploaded').length+(trEvidence(t)?0:1):0;
const trTabs=['overview','attendance','survey','assessment','documents','audit'];
const trTabLabel={overview:'Overview',attendance:'Attendance',survey:'Survey',assessment:'Assessment',documents:'Documents',audit:'Audit trail'};
function mandatoryStatus(m){if(m.exempt)return 'Exempted';const t=trOf(m.tr),p=t.participants.find(x=>x.emp===m.emp);if(t.status==='Completed'&&p&&(p.attendance==='Present'||p.attendance==='Late')&&trPassed(t,p)&&p.certificate==='Uploaded')return 'Completed';if(t.status==='Completed'&&p&&p.attendance==='Absent')return atOverdue(m.due)?'Overdue':'Pending';if(atOverdue(m.due))return 'Overdue';return 'Pending';}
